"OLAYLAR_DUNYA_AVRUPA_MO:-0545-01-01:0":{"b": ["Vita vya Pallene: Peisistratos alianzisha udhalimu wa kudumu huko Atina", "671f71c2"], "d": ["Katika jaribio la tatu Peisistratos aliwashinda Waatina huko Pallene na akaanzisha udhalimu wa kudumu (546/5); ulidumu hadi 527.", "0647a94e"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0545-01-01:1":{"b": ["Vita vya Thyrea (Mabingwa): Sparta ilimshinda Argos, Kynouria ilibaki kwa Sparta", "35b7197a"], "d": ["Wapiganaji 300 waliochaguliwa kila upande walipigana; Sparta ilipata Thyreatis.", "8d9b3c39"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0549-01-01:0":{"b": ["Miltiades (Mzee) alianzisha utawala huko Khersonesos ya Thrake", "6da9fbe4"], "d": ["Miltiades mwenye asili ya Atina alianzisha utawala nusu huru kwenye peninsula ya Gallipoli.", "88847c09"]},
