"OLAYLAR_DUNYA_AVRUPA_MO:-0573-01-01:0":{"b": ["Emporion (Ampurias) ilianzishwa na Wafokaia", "c4706f54"], "d": ["Makazi ya Massalia kwenye pwani ya Iberia; uwepo wa Wagiriki huko Hispania.", "525d2aff"]},
