"OLAYLAR_DUNYA_AVRUPA_MO:-0597-01-01:0":{"b": ["Kamarina ilianzishwa na Syracuse", "47055e49"], "d": ["Syracuse ilianzisha koloni kusini mashariki (miaka 135 baada ya Syracuse).", "40d8cb35"]},
