"OLAYLAR_DUNYA_AVRUPA_MO:-0656-01-01:0":{"b": ["Kypselos alianzisha udhalimu huko Korintho, Bakkhiadai walipinduliwa", "f4f32246"], "d": ["Kypselos aliipindua oligarkia ya Bakkhiadai na akaanzisha udhalimu wa muda mrefu.", "790b64e0"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0668-01-01:0":{"b": ["Vita vya Hysiai: Argos ilimshinda Sparta chini ya Pheidon", "47a0d03b"], "d": ["Ukuu wa Argos wakati wa Pheidon (tarehe na uhalisia wa kihistoria vinajadiliwa).", "c3d09b3d"]},
